begin
 if regexp_replace(coalesce(e->>'key',e->>'sportKey',e->>'sportDomainId',''),'^sport:','') !~ '^cricket(-women)?$' and coalesce(e->>'competitionId','') not like '%cricket%' then return true; end if;
