 women := concat_ws(' ',e->>'gender',e->>'genderCategory',e->>'competitionId',e->>'competitionName',e->>'name') ~* 'women|female|wbbl' or exists(select 1 from jsonb_array_elements_text(ids) x where x like '%-women');
