 return coalesce(format_value in ('Tests','ODIs','T20Is') and jsonb_array_length(ids)>=2 and not exists(select 1 from jsonb_array_elements_text(ids) x where not(policy->'nationalTeams' ? replace(x,'team:cricket:',''))),false);
